/* **************************************** */
/*          INSTRUCCIONES INICIALES         */
/* **************************************** */
SET CLIENT_ENCODING TO 'UTF8';

/* **************************************** */
/*                  ESQUEMA                 */
/* **************************************** */
-- usuario
create table public.usuario (
  id bigint primary key not null,
  nombre character varying(100) not null,
  apellido character varying(100) not null,
  correo character varying(254) not null,
  contrasena character varying(64) not null,
  telefono character varying(15) not null,
  borrado boolean not null
);
create unique index usuario_correo_key on usuario using btree (correo);
create unique index usuario_telefono_key on usuario using btree (telefono);
create index usuario_correo_like on usuario using btree (correo);
create index usuario_telefono_like on usuario using btree (telefono);

-- conductor
create table public.conductor (
  id bigint primary key not null,
  nombre character varying(100) not null,
  apellido character varying(100) not null,
  correo character varying(254) not null,
  contrasena character varying(64) not null,
  telefono character varying(15) not null,
  foto_perfil character varying(254) not null,
  borrado boolean not null
);
create unique index conductor_correo_key on conductor using btree (correo);
create unique index conductor_telefono_key on conductor using btree (telefono);
create index conductor_correo_like on conductor using btree (correo);
create index conductor_telefono_like on conductor using btree (telefono);

-- automovil
create table public.automovil (
  id bigint primary key not null,
  marca character varying(100) not null,
  anio_fabricacion smallint not null,
  placa character varying(15) not null,
  color character varying(100) not null,
  borrado boolean not null,
  conductor_id bigint not null,
  foreign key (conductor_id) references public.conductor (id) on update no action on delete no action
);
create unique index automovil_placa_key on automovil using btree (placa);
create index automovil_placa_like on automovil using btree (placa);
create index automovil_conductor_id on automovil using btree (conductor_id);

-- viaje
create table public.viaje (
  id bigint primary key not null,
  fecha_inicio timestamp with time zone not null,
  fecha_fin timestamp with time zone,
  distancia smallint,
  calificacion_pasajero smallint,
  calificacion_conductor smallint,
  automovil_id bigint not null,
  conductor_id bigint not null,
  pasajero_id bigint not null,
  foreign key (automovil_id) references public.automovil (id) on update no action on delete no action,
  foreign key (conductor_id) references public.conductor (id) on update no action on delete no action,
  foreign key (pasajero_id) references public.usuario (id) on update no action on delete no action
);
create index viaje_automovil_id on viaje using btree (automovil_id);
create index viaje_conductor_id on viaje using btree (conductor_id);
create index viaje_pasajero_id on viaje using btree (pasajero_id);

-- reporte
create table public.reporte (
  id bigint primary key not null,
  fecha date not null,
  detalles text not null,
  viaje_id bigint not null,
  foreign key (viaje_id) references public.viaje (id) on update no action on delete no action
);
create index reporte_viaje_id on reporte using btree (viaje_id);


/* **************************************** */
/*                   DATOS                  */
/* **************************************** */
-- usuario
COPY public.usuario (id, nombre, apellido, correo, contrasena, telefono, borrado) FROM stdin WITH (FORMAT CSV, DELIMITER ',');
